import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long[] price = new long[(int) n];
        for (int i = 0; i < price.length; i++) price[i] = Long.parseLong(next());

        int len = (int) n;
        long[] best = new long[len + 1];
        for (int length = 1; length <= len; length++) {
            long top = 0;
            for (int cut = 1; cut <= length; cut++) {
                top = Math.max(top, price[cut - 1] + best[length - cut]);
            }
            best[length] = top;
        }
        System.out.println(best[len]);
    }
}
